import assert from 'node:assert/strict';import{createHash}from'node:crypto';
export function priorButterflyModel(s){if(s.includes('ANAX_MODEL_BEGIN'))s=priorAnaxModel(s);s=s.replace(/(from\s*['"]\.\/[^'"?\n]+)(?:\?[^'"\n]*)?(['"])/g,'$1$2');const added="      // BUTTERFLY_ARRIVAL_RENDER_BEGIN\n      const wingFlight=!inspection&&Number.isFinite(item.butterflyWingBlend)?item.butterflyWingBlend:flight;\n      const angle=inspection?.12+Math.sin(time*1.4)*.06:restAngle*(1-wingFlight)+flightAngle*wingFlight+warning*(.28+.07*Math.sin(time*14));\n      // BUTTERFLY_ARRIVAL_RENDER_END",old="      const angle=inspection?.12+Math.sin(time*1.4)*.06:restAngle*(1-flight)+flightAngle*flight+warning*(.28+.07*Math.sin(time*14));";assert.equal(s.split(added).length-1,1);s=s.replace(added,old);assert.equal(createHash('sha256').update(s).digest('hex'),'2881e9702f4193ac947cc6bbf2ca432f718eb25321837b015eba3d572a44bbeb');return s;}
